<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\DispatchService;use App\Support\Url;Auth::requirePermission('TRIP_VIEW_OPERATIONS');$a=Auth::can('SHIPMENT_MANAGE')?DispatchService::assignments():[];$rows=DispatchService::listAll();$pageTitle='Shipments & Trips';require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1>Shipments & trips</h1><p>Plan assigned transport, receive Driver readiness and control dispatch.</p></div><span class="badge">Phase 8</span></div><div class="card"><h2>Assignments awaiting planning</h2><?php foreach($a as$x):?><p><a href="<?=h(Url::to('operations/shipment-create.php?assignment_id='.$x['assignment_id']))?>"><?=h($x['assignment_ref'].' · '.$x['load_ref'].' · '.$x['registration_number'])?></a></p><?php endforeach;if(!$a):?><p class="muted">None.</p><?php endif;?></div><div class="card table-wrap" style="margin-top:18px"><table><thead><tr><th>Shipment</th><th>Load</th><th>Route</th><th>Truck / Driver</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=h($r['shipment_ref'])?></td><td><?=h($r['load_ref'])?></td><td><?=h($r['origin_city'].' → '.$r['destination_city'])?></td><td><?=h($r['registration_number'].' · '.$r['driver_name'])?></td><td><span class="status-pill status-<?=h($r['current_status'])?>"><?=h(str_replace('_',' ',$r['current_status']))?></span></td><td><a href="<?=h(Url::to('operations/trip-view.php?id='.$r['trip_id']))?>">Open</a></td></tr><?php endforeach;?></tbody></table></div><?php require BASE_PATH.'/app/Views/layout/footer.php';
